  "exports.eyebrow": "Dados",
  "exports.title": "Exportações e backups",
  "exports.subtitleStart": "Os downloads são sempre limitados a",
  "exports.subtitleRest": ". Cada arquivo é identificado com o nome da empresa e a data em que foi criado.",
  "exports.createBusinessFirst": "Crie uma empresa primeiro — as exportações pertencem a uma empresa, não ao aplicativo.",
  "exports.lockedTitle": "As exportações em CSV e Excel são um recurso do plano Business",
  "exports.lockedDesc": "Seu espaço de trabalho está no plano Essentials. O Business adiciona exportações em CSV e Excel, avaliação de estoque, produtos e equipe ilimitados, fornecedores, compras e kits.",
  "exports.seeBusiness": "Veja o que o Business inclui",
  "exports.whatTheseAre": "O que são esses arquivos",
  "exports.about1": "Todo conjunto de dados vem como CSV ou uma pasta de trabalho real do Excel (.xlsx) — a pasta de trabalho completa do inventário é somente em Excel, com uma planilha por conjunto de dados. Os arquivos CSV abrem no Excel, Numbers, Google Sheets e na maioria dos aplicativos de estoque. Texto em UTF-8, vírgulas entre aspas, quebras de linha nas observações e zeros à esquerda nos códigos são todos preservados, e as células que começam como uma fórmula são neutralizadas para que a planilha as abra como texto.",
  "exports.about2": "Nos arquivos do Excel, SKUs, UPCs, ISBNs e códigos de barras são células de texto — nunca notação científica e nunca com zeros removidos — com larguras de coluna, filtros de cabeçalho e formatos de moeda ou quantidade aplicados. A pasta de trabalho completa do inventário mantém produtos, níveis de estoque, locais e movimentações em planilhas separadas.",
  "exports.about3": "Exportações muito grandes param em 20.000 linhas por conjunto de dados — quando isso acontece, o nome do arquivo indica (truncated-20000), para que um arquivo parcial nunca passe por completo.",
  "exports.about4": "Um backup é um instantâneo dos seus dados, não uma restauração com um clique. Restaurá-lo é um trabalho manual, com revisão primeiro, então guarde o arquivo em segurança — nada no aplicativo pode recriar uma empresa excluída a partir dele ainda. O código do aplicativo e os backups da plataforma Base44 são tratados separadamente desses arquivos.",
  "exports.about5": "Fotos e anexos são listados como seus links armazenados — os arquivos de imagem em si não são incluídos no download.",
  "exports.backupTitle": "Backup completo",
  "exports.backupDesc": "Um arquivo com os produtos, locais, níveis de estoque, livro de movimentações completo, fornecedores, compras, pedidos, devoluções, contagens e listagens desta empresa — além das configurações do perfil. Guarde-o em um local sob seu controle.",
  "exports.backupIncludes1": "Produtos, códigos, custos e observações",
  "exports.backupIncludes2": "Locais e quantidades por local",
  "exports.backupIncludes3": "Todas as movimentações, com responsável e horário",
  "exports.backupIncludes4": "Compras, pedidos, devoluções e contagens",
  "exports.buildingBackup": "Criando backup…",
  "exports.backupJson": "Backup (JSON)",
  "exports.excelSnapshot": "Instantâneo em Excel",
  "exports.recordsDone": "{count} registros",
  "exports.backupDownloaded": "Backup baixado",
  "exports.backupFailed": "Falha no backup",
  "exports.backupFailedDesc": "Não foi possível ler os dados da empresa. Tente novamente.",
  "exports.exportedTitle": "{title} exportado",
