  "import.eyebrow": "Dados",
  "import.title": "Central de importação",
  "import.subtitleStart": "Três operações de planilha separadas, para que uma correção de preço nunca chegue como um recebimento de estoque. Tudo vai para",
  "import.subtitleRest": " somente, e nada é gravado até que um teste seja aprovado.",
  "import.createBusinessFirst": "Crie uma empresa primeiro — os produtos importados pertencem a uma empresa.",
  "import.createBusinessFirstShort": "Crie uma empresa primeiro.",
  "import.whatEachDoes": "O que cada operação faz",
  "import.createTitle": "Criar novos produtos",
  "import.createDesc": "adiciona linhas que ainda não estão no catálogo. SKUs e códigos de barras duplicados já em uso são ignorados, e o estoque inicial pode ir para um local de sua escolha como um recebimento.",
  "import.updateTitle": "Atualizar produtos existentes",
  "import.updateDesc": "corresponde cada linha por SKU ou ID de registro e mostra o valor antigo ao lado do novo valor proposto. Células em branco mantêm o valor salvo, a menos que você peça para limpar os campos em branco, e as quantidades nunca são alteradas.",
  "import.receiveModeTitle": "Receber estoque",
  "import.receiveModeDesc": "adiciona quantidades recebidas a um local e grava um recebimento no livro de movimentações para cada linha. Cada lote é marcado, para que a mesma planilha não possa ser recebida duas vezes.",
  "import.excelNote": "As pastas de trabalho do Excel (.xlsx) são lidas diretamente — escolha a planilha e as colunas são correspondidas para você. Os códigos permanecem inteiros: um UPC salvo como texto mantém seus dígitos e zeros à esquerda. Linhas que não podem ser importadas são listadas com um motivo",
  "import.excelNoteDownload": " e podem ser baixadas como arquivo.",
  "import.excelNoteFix": ", para que você possa corrigi-las e tentar novamente.",
  "import.matchColumns": "Corresponder as colunas",
  "import.columnFallback": "Coluna {column}",
  "import.ignoreColumn": "Ignorar esta coluna",
