  "print.supplierBlockedDesc": "Documentos de fornecedor acompanham o plano Business — fornecedores, compras e pedidos de compra. Tudo o que você tem agora continua funcionando.",
  "print.seeBusiness": "Veja o que o Business inclui",
  "print.nothingToPrint": "Nada para imprimir ainda",
  "print.pickOrderHint": "Escolha um pedido de compra da lista para pré-visualizar o documento.",
  "print.pickCustomerOrderHint": "Escolha um pedido de cliente da lista para pré-visualizar o documento.",
  "print.pickReturnHint": "Escolha uma devolução registrada da lista para pré-visualizar o documento.",
  "print.chooseStyleHint": "Escolha um estilo e depois escolha produtos da lista. A pré-visualização mostra exatamente o que sai da impressora.",
  "print.howToReach": "Como acessar sua impressora",
  "print.howIntro": "Este aplicativo se conecta a impressoras que você já possui — ele não é uma impressora. Há quatro maneiras de acessar uma, e as etiquetas são impressas em ambos os planos por qualquer uma delas. Guias de remessa, pedidos de compra, documentos de fornecedor e relatórios são somente do plano Business, independentemente da conexão.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "A partir desta página, no Chrome ou Edge para desktop e no Chrome para Android: escolha sua impressora de etiquetas e as etiquetas vão direto para ela. Não funciona no Safari do iOS — em um iPhone, a impressão Bluetooth vem com o aplicativo móvel. Uma impressora que só fala Zebra ZPL ou a linguagem própria da Brother não entenderá as etiquetas que esta página envia; isso é testado em impressoras reais antes de ser considerado funcional.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Instale a impressora no Wi-Fi da sua loja e depois use o botão Imprimir — ele imprime pela impressora instalada neste computador, pela rede da loja. Em um iPhone, o AirPrint é integrado: uma impressora AirPrint no mesmo Wi-Fi aparece na tela de impressão, sem cabo e sem aplicativo, e o aplicativo não precisa de código específico para AirPrint. A impressora deve ser compatível com AirPrint (a maioria das novas é) e o telefone e a impressora devem estar no mesmo Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Conecte a impressora à rede da sua loja com um cabo Ethernet, instale-a no computador e imprima pelo botão Imprimir. Ethernet é um caminho para desktop e computador — iPhones não usam cabos Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Conecte a impressora ao computador com seu cabo e use o botão Imprimir — ele imprime pela impressora instalada ali. Em um telefone Android com cabo USB OTG, o botão USB acima fala direto com a impressora. iPhones não podem imprimir por USB diretamente — não há WebUSB ali — então use Wi-Fi / AirPrint, ou Bluetooth pelo aplicativo móvel.",
  "print.howCordsLead": "Os cabos ainda atendem iPhones, a um passo de distância.",
  "print.howCordsBody": "Uma impressora USB conectada ao computador da loja, ou uma impressora Ethernet conectada à rede, aparece no seu iPhone pelo Wi-Fi da loja (AirPrint / impressora compartilhada) — os cabos colocam a impressora na rede de forma sólida, e o telefone a acessa sem fio.",
  "print.howOfflineLead": "Se a internet cair,",
  "print.howOfflineBody": "as etiquetas e documentos já nesta página ainda são impressos — o botão Imprimir, o PDF de etiquetas, Bluetooth e USB não precisam de conexão. O que precisa de internet é carregar a página e seus produtos em primeiro lugar. O modo totalmente offline (trabalhar no aplicativo sem nenhuma conexão) é uma construção separada e maior, e não é prometido aqui.",
