  "settings.cancelTerms.appleLink": "Instruções de cancelamento da Apple",
  "settings.cancelTerms.googlePlayLink": "Instruções de cancelamento do Google Play",
  "settings.cancelTerms.graceTitle": "Após o fim do período pago — 15 dias de carência e, depois, exclusão:",
  "settings.cancelTerms.intro": "Estes são os termos das assinaturas pagas do Luminous StockHaven. A cobrança das assinaturas feitas pelo site é feita pelo Stripe. Você pode cancelar sua assinatura a qualquer momento usando o botão Cancelar assinatura abaixo — não é necessária aprovação da equipe. Solicitações de cancelamento e reembolso também podem ser tratadas pelo contato oficial de suporte ao cliente, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Você pode cancelar sua assinatura a qualquer momento. Não é necessária aprovação da equipe. As renovações futuras só são interrompidas depois que a provedora de cobrança confirma o cancelamento.",
  "settings.cancelTerms.noApprovalTitle": "Cancelar sem aprovação:",
  "settings.cancelTerms.paymentBody": "Nos testes pagos, o período de teste de sete dias exige um método de pagamento no cadastro. Se não for cancelado dentro do prazo de cancelamento do teste aplicável, o plano mensal selecionado será cobrado automaticamente após o teste. O preço, a data da primeira cobrança e o prazo de cancelamento específico da provedora devem ser exibidos durante o cadastro. A cobrança do teste é feita pelo Stripe.",
  "settings.cancelTerms.paymentTitle": "Método de pagamento e renovação automática:",
  "settings.cancelTerms.remainingBody": "Se você já pagou por um período de cobrança, pode manter o acesso até essa data verificada de pagamento válido até. Um encerramento antecipado exige a confirmação adequada da provedora e qualquer tratamento de reembolso aplicável. O acesso ao teste gratuito termina de acordo com a data de encerramento do teste confirmada pela provedora.",
  "settings.cancelTerms.remainingTitle": "Acesso restante:",
  "settings.cancelTerms.storesBody": "Se algum dia você assinar pelo Google Play ou pela Apple App Store, sua assinatura será cobrada e gerenciada por essa loja. Pode ser necessário cancelá-la diretamente na seção de assinaturas da mesma conta do Google ou da Apple usada para assinar. Cancelar uma assinatura separada do site, desinstalar este app ou solicitar a exclusão da conta do Luminous StockHaven não cancela automaticamente uma assinatura cobrada por uma loja. Verifique seu recibo de compra para confirmar quem faz a cobrança.",
  "settings.cancelTerms.storesTitle": "Assinaturas do Google Play e da Apple App Store (se algum dia você assinar por uma loja):",
  "settings.cancelTerms.title": "Termos e condições de cancelamento",
  "settings.cancelTerms.trialBody": "O período de teste de sete dias pode ser usado apenas uma vez por cliente elegível. Cancelar um teste ou uma assinatura não concede outro teste; clientes que retornam devem escolher uma assinatura paga.",
  "settings.cancelTerms.trialTitle": "Um teste gratuito:",
  "settings.canceled.endsOn": "Esta assinatura está cancelada e termina em {date}. Você mantém acesso completo até lá.",
  "settings.delete.checking": "Verificando se já existe uma solicitação de exclusão…",
  "settings.delete.description": "Solicitar a remoção da sua conta de acesso ao Luminous StockHaven.",
  "settings.delete.dialogDescription": "Isso solicita uma análise da exclusão da conta. Não remove imediatamente seu login nem seu estoque e não cancela nenhuma assinatura do Stripe. Digite {word} para confirmar que deseja enviar a solicitação.",
  "settings.delete.dialogTitle": "Solicitar exclusão da conta",
  "settings.delete.enterDelete": "Digite {word} para confirmar",
  "settings.delete.exportFirst": "Exporte seu estoque primeiro se precisar manter seus registros.",
  "settings.delete.intro": "Enviar uma solicitação não exclui imediatamente sua conta, suas empresas nem seu estoque. As solicitações são analisadas separadamente antes que a exclusão possa ser concluída. Esta solicitação não cancela uma assinatura do Stripe nem interrompe cobranças futuras; o cancelamento da assinatura deve ser tratado separadamente pela provedora de cobrança.",
