  "settings.trial.cancelKeeps": "Cancelar durante o teste mantém seus 7 dias completos — o acesso termina em {date} e você não será cobrado.",
  "staff.access.noSeatBody": "Sua conta não tem um lugar de funcionário para esta empresa, por isso o estoque dela permanece fechado. Peça ao proprietário que adicione você em Funcionários e funções.",
  "staff.access.noSeatTitle": "Esta empresa não está aberta para o seu login",
  "staff.access.pendingBody": "Esta empresa tem um convite para o seu e-mail que ainda não foi ativado. Peça ao proprietário que defina seu status de funcionário como ativo. Nada aqui fica visível até lá.",
  "staff.access.pendingTitle": "Seu convite ainda não está ativo",
  "staff.access.signOut": "Sair",
  "staff.access.suspendedBody": "Um administrador suspendeu esta conta de funcionário para a empresa ativa. Peça que ele defina você novamente como ativo e, depois, entre novamente.",
  "staff.access.suspendedTitle": "Seu acesso está pausado",
  "staff.addFirst": "Adicionar o primeiro funcionário",
  "staff.addMember": "Adicionar funcionário",
  "staff.emptyBody": "Adicione uma pessoa, dê a ela uma função e as permissões correspondentes, e ela será convidada por e-mail para entrar nesta empresa.",
  "staff.emptyTitle": "Nenhum funcionário ainda",
  "staff.eyebrow": "Equipe",
  "staff.how.p1": "Cada membro tem uma função e sua própria lista de permissões, assim você pode partir de uma função e alterar uma coisa sem criar uma nova função. Editar uma função não reescreve os membros que já estão nela — abra um membro para reaplicar os padrões da função dele.",
  "staff.how.p2": "Funções personalizadas são um recurso do Business: o Essentials usa as cinco funções integradas (Proprietário, Gerente, Estoquista, Vendedor, Visualizador).",
  "staff.how.p3": "Os convites são enviados por e-mail. Um membro só pode entrar depois de aceitar, e remover alguém desta lista não exclui a conta dele no app.",
  "staff.how.p4": "Uma loja é o local ao qual uma pessoa é atribuída. Isso fica registrado no cartão dela; o que ela pode abrir continua sendo decidido pela função e pelas permissões dela.",
  "staff.how.p5": "As permissões decidem o que cada pessoa pode abrir: itens de menu fora da função dela ficam ocultos, e um endereço bloqueado exibe um aviso de “não está na sua função” em vez da página. Uma alteração é aplicada na próxima vez que essa pessoa carregar o app; suspender um membro bloqueia o acesso dele por completo.",
  "staff.how.p6": "Administradores podem ver e alterar todos os dados, gerenciar usuários e funções do app e nunca são limitados por uma função de funcionário. Alguém sem registro de funcionário — o proprietário de uma nova empresa — mantém acesso completo.",
