  "payroll.dd.savings": "Poupança",
  "payroll.dd.steps.body": "1. Você precisa de uma conta bancária empresarial que possa enviar pagamentos ACH. 2. Colete um formulário de autorização assinado de cada membro da equipe - um cheque anulado ajuda a confirmar os números. 3. Envie a folha de pagamento 2 a 3 dias úteis antes do dia do pagamento para o dinheiro chegar a tempo. 4. A maioria dos estados exige o consentimento por escrito do membro da equipe. Este app coleta os formulários e orienta você em cada etapa - o envio do dinheiro em si é feito pelo seu próprio banco.",
