  "workforce.unscheduledNote": "Nenhum turno está programado para hoje, portanto este horário será marcado como sem escala.",
  "workforce.inbox.help": "Eventos de ponto, respostas sobre folgas, tarefas, holerites e mudanças de escala da sua equipe, dos mais recentes para os mais antigos.",
  "workforce.messages.back": "Todas as conversas",
  "workforce.messages.empty": "Nenhuma conversa ainda. Comece uma com o botão acima.",
  "workforce.messages.emptyThread": "Nenhuma mensagem ainda. Diga olá para começar.",
  "workforce.messages.help": "Mensagens privadas individuais com sua equipe — sem precisar de outro app. Somente as duas pessoas de uma conversa podem lê-la, além do proprietário da empresa, que supervisiona a loja.",
  "workforce.messages.new": "Nova mensagem",
