  "auth.sameEmailNotice": "Já tem nosso app pelo Google Play ou pela App Store? Use o mesmo e-mail aqui — aquele com que você entra no app — para que sua loja e seu estoque venham com você. Um e-mail diferente começa uma vitrine totalmente nova e vazia.",
