  "recovery.title": "Recuperar sua conta",
  "recovery.subtitle": "Perdeu o acesso ao e-mail da sua conta? Suas chaves reservas podem trazer você de volta à sua loja.",
  "recovery.remembered": "Lembrou, afinal?",
