  "recovery.genericError": "Algo deu errado. Tente novamente.",
  "recovery.emailLabel": "E-mail da sua conta",
  "recovery.backupCodeLabel": "Um dos seus códigos de backup",
  "recovery.backupCodeHint": "Os códigos de uso único que você salvou em Configurações → Segurança. Cada código funciona exatamente uma vez.",
