  "recovery.emailMeCode": "Enviar um código para meu e-mail de backup",
  "recovery.emailMeCodeHint": "Se você configurou um e-mail de backup, enviaremos um código de 6 dígitos para lá. Para proteger sua conta, esta página sempre responde da mesma forma — tenha um código sido enviado ou não.",
  "recovery.codeSent": "Se o seu e-mail de backup estiver cadastrado, um código de 6 dígitos está a caminho agora. Ele expira em 10 minutos.",
  "recovery.codeLabel": "Código de 6 dígitos",
