  "rewards.subtitle": "Diga obrigado com uma recompensa — um percentual de desconto, um vale-presente ou qualquer coisa que você descrever.",
  "rewards.title": "Recompensas e incentivos",
  "rewards.value.giftCard": "Vale-presente de {value}",
  "rewards.value.percentOff": "{percent}% de desconto na loja",
  "rewards.void": "Cancelar",
  "rewards.voided": "Recompensa cancelada.",
  "workforce.tab.rewards": "Recompensas",
  "training.lessons.mgr-give-rewards.step1": "Abra Equipe e toque em Recompensas. Escolha o membro da equipe e depois o tipo: um percentual de desconto na loja, um vale-presente ou outra coisa que você descrever com suas próprias palavras.",
  "training.lessons.mgr-give-rewards.step2": "Dê à recompensa um nome curto e uma observação, se quiser. A pessoa recebe um aviso imediatamente, e a recompensa aguarda em Minhas recompensas dela, com seu próprio código.",
  "training.lessons.mgr-give-rewards.step3": "O limite, por design: você recompensa SOMENTE FUNCIONÁRIOS. Você não pode recompensar a si mesmo nem outro gerente — recompensar um gerente é decisão do proprietário, e o app recusará claramente.",
  "training.lessons.mgr-give-rewards.step4": "No caixa, digite o código que o membro da equipe mostrar e marque como usado — cada código funciona uma vez. Você pode cancelar uma recompensa que deu se os planos mudarem; os presentes do proprietário são do proprietário para cancelar.",
  "training.lessons.mgr-give-rewards.title": "Dar recompensas aos seus funcionários",
  "training.lessons.owner-give-rewards.step1": "Recompensas ficam em Equipe, na aba Recompensas, e são somente do plano Business — no Essentials, a aba mostra uma porta trancada, para que sua equipe veja o que o plano maior oferece.",
  "training.lessons.owner-give-rewards.step2": "Você pode recompensar QUALQUER pessoa da equipe — funcionários e gerentes. Escolha a pessoa e depois o tipo: um percentual de desconto na loja (qualquer percentual que você escolher), um vale-presente para qualquer lugar ou qualquer incentivo que você descrever com suas próprias palavras.",
  "training.lessons.owner-give-rewards.step3": "A recompensa chega com seu próprio código de uso único e toca o sino da pessoa. Ela mostra o código no caixa; um proprietário ou gerente o digita para marcar como usado.",
  "training.lessons.owner-give-rewards.step4": "Um comprovante de recompensa impresso ou compartilhado traz somente o nome da SUA empresa — nunca o do app. É o agradecimento da sua loja, não um anúncio.",
  "training.lessons.owner-give-rewards.title": "Dar recompensas (plano Business)",
  "training.lessons.owner-rewards-oversight.step1": "Seu gerente também pode dar recompensas — somente para funcionários. O app recusa um gerente recompensando a si mesmo ou outro gerente; recompensar um gerente é sempre decisão sua.",
  "training.lessons.owner-rewards-oversight.step2": "Você vê todas as recompensas da empresa no Histórico de recompensas: quem deu, quem recebeu e se ela está pronta, usada ou cancelada. Um gerente vê apenas as recompensas que deu e as que recebeu.",
  "training.lessons.owner-rewards-oversight.step3": "Você pode cancelar qualquer recompensa, incluindo uma que seu gerente deu. Um gerente pode cancelar os próprios presentes, mas nunca os seus.",
  "training.lessons.owner-rewards-oversight.step4": "Cada código funciona exatamente uma vez, e uma recompensa cancelada nunca pode ser usada — o histórico sempre mostra como uma recompensa terminou.",
  "training.lessons.owner-rewards-oversight.title": "Supervisionar recompensas: as entregas do seu gerente",
  "training.lessons.staff-your-rewards.step1": "Quando seu gerente ou o proprietário der uma recompensa a você, seu sino toca. Abra Equipe e toque em Recompensas para vê-la em Minhas recompensas.",
  "training.lessons.staff-your-rewards.step2": "Cada recompensa tem seu próprio código. Guarde-o para você — quem mostrar o código no caixa é quem usa a recompensa.",
  "training.lessons.staff-your-rewards.step3": "Para usá-la, mostre o código quando comprar. A pessoa no caixa o digita e marca como usado — cada código funciona exatamente uma vez.",
  "training.lessons.staff-your-rewards.step4": "Recompensas são um mimo do plano Business. Se a sua loja não estiver no Business, a aba Recompensas mostra uma porta trancada — é o plano, não um erro.",
  "training.lessons.staff-your-rewards.title": "Suas recompensas: encontrar seu código e usá-lo",
  "training.module.rewards": "Recompensas e incentivos",
